from dataclasses import dataclass

@dataclass(frozen=True)
class DiscountCode:
    code: str
    rate: float

DISCOUNT_CODES = {
    "SAVE10": DiscountCode("SAVE10", 0.10),
    "SAVE20": DiscountCode("SAVE20", 0.20),
    "HALFOFF": DiscountCode("HALFOFF", 0.50),
}

class Cart:
    def __init__(self):
        self.items = []
        self.discount_code = None  # type: DiscountCode | None

    def add_item(self, name: str, price: float, qty: int) -> None:
        self.items.append({"name": name, "price": price, "qty": qty})

    @property
    def subtotal(self) -> float:
        return sum(item["price"] * item["qty"] for item in self.items)

    def set_discount(self, code: str | None) -> None:
        self.discount_code = DISCOUNT_CODES.get(code)

    @property
    def discount(self) -> float:
        if self.discount_code:
            return self.subtotal * self.discount_code.rate
        return 0.0

    @property
    def tax(self) -> float:
        return (self.subtotal - self.discount) * 0.08

    @property
    def total(self) -> float:
        return self.subtotal - self.discount + self.tax
